    // Write a function to count number items that are identical in the same position of three given array lists.
    public static long countSamepair(ArrayList<Long> list1, ArrayList<Long> list2, ArrayList<Long> list3) {
        long count = 0;
        int size = Math.min(list1.size(), Math.min(list2.size(), list3.size()));

