    public static float othersideRightangle(long w, long h) {
        // Calculate the square of the hypotenuse using the Pythagorean theorem
        long hypotenuseSquared = w * w - h * h;

        // Calculate the third side (hypotenuse)
        float hypotenuse = (float) Math.sqrt(hypotenuseSquared);

        return hypotenuse;
    }

}

