// Write a function to sort the given array list by using shell sort.
public class MBPP_428_shell_sort {

    // Shell Sort algorithm implementation
    public static ArrayList<Long> shellSort(ArrayList<Long> my_list) {
        int n = my_list.size();
        int gap = n / 2;

        // Continue sorting until the gap is 1
        while (gap > 0) {
            // Perform insertion sort on subarrays of size 'gap'
            for (int i = gap; i < n; i++) {
                long temp = my_list.get(i);
                int j;
                // Shift elements greater than 'temp' to the right by 'gap'
                for (j = i; j >= gap && my_list.get(j - gap) > temp; j -= gap) {
                    my_list.set(j, my_list.get(j - gap));
                }
                // Insert 'temp' at its correct position
                my_list.set(j, temp);
            }
