    public static ArrayList<Pair<String, Long>> sortCounter(HashMap<String,Long> dict1) {
        // Create a list of entries from the map
        List<Map.Entry<String, Long>> entryList = new ArrayList<>(dict1.entrySet());

        // Sort the list based on the values in descending order
        entryList.sort(Map.Entry.comparingByValue(Comparator.reverseOrder()));

