        ArrayList<Pair<String, Long>> sortedPairs = new ArrayList<>();
        for (Map.Entry<String, Long> entry : entryList) {
            sortedPairs.add(Pair.with(entry.getKey(), entry.getValue()));
        }

        return sortedPairs;
    }

}

