    public static long bigSum(ArrayList<Long> nums) {
        if (nums == null || nums.isEmpty()) {
            throw new IllegalArgumentException("Array list cannot be null or empty");
        }

        long min = Long.MAX_VALUE;
        long max = Long.MIN_VALUE;

        for (Long num : nums) {
            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        return max - min;
    }

}

