    // Write a javathon function to find the difference between the sum of cubes of the first n natural numbers and the sum of the first n natural numbers.
    public static long difference(long n) {
        long sumOfCubes = 0;
        long sumOfNumbers = 0;

        for (long i = n; i >= 1; i--) {
            sumOfCubes += i * i * i;
            sumOfNumbers += i;
        }

        return sumOfCubes - sumOfNumbers;
    }

}

