    // Write a javathon function to find the largest number that can be formed with the given array list of digits.
    public static long findMaxNum(ArrayList<Long> arr) {
        if (arr == null || arr.isEmpty()) {
            return 0;
        }

        // Convert each digit to a string for easy comparison
        List<String> strArr = new ArrayList<>();
        for (Long num : arr) {
            strArr.add(num.toString());
        }

        // Sort the array based on a custom comparator
        Collections.sort(strArr, new Comparator<String>() {
            public int compare(String a, String b) {
                String order1 = a + b;
                String order2 = b + a;
                return order2.compareTo(order1);
            }
        });

        // If the largest number starts with '0', return 0
        if (strArr.get(0).equals("0")) {
            return 0;
        }

        // Concatenate the sorted strings to form the largest number
        StringBuilder maxNum = new StringBuilder();
        for (String numStr : strArr) {
            maxNum.append(numStr);
        }

        // Convert the result back to a long
        return Long.parseLong(maxNum.toString());
    }

}

