    public static long countSamePair(ArrayList<Long> nums1, ArrayList<Long> nums2) {
        long count = 0;
        for (int i = 0; i < nums1.size(); i++) {
            if (nums1.get(i).equals(nums2.get(i))) {
                count++;
            }
        }
        return count;
    }

}

