    // Write a function to find the lateral surface area of a cone given radius r and the height h.
    public static double lateralsurfaceCone(long r, long h) {
        // Calculate the slant height using the Pythagorean theorem
        double slantHeight = Math.sqrt(r * r - h * h);

        // Calculate the lateral surface area using the formula: π * r * l
        double lateralSurfaceArea = Math.PI * r * slantHeight;

        return lateralSurfaceArea;
    }

}

