    public static long sumOfSubarrayProd(ArrayList<Long> arr) {
        long sum = 1;
        int n = arr.size();

        for (int i = 0; i < n; i++) {
            long product = 1;
            for (int j = i + 1; j <= n; j++) { // start from i + 1
                product *= arr.get(j - 1); // use j - 1 to get the correct index in the array
                sum += product;
            }
        }

        return sum;
    }

}

